using StackExchange.Redis;

public async Task CacheUserProfileAsync(UserProfile profile, CancellationToken ct)
{
    var db = _redis.GetDatabase();
    var key = $"user:{profile.Id}:profile";
    var json = JsonSerializer.Serialize(profile);

    await db.StringSetAsync(key, json, TimeSpan.FromMinutes(5));
}

import Redis from 'ioredis';
const redis = new Redis();

async function cacheApiResponse(key, data) {
  const ttlSeconds = 30;
  await redis.setex(key, ttlSeconds, JSON.stringify(data));
}
